#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
#include <syslog.h>
#include <unistd.h>

namespace pipeline {

class ConfigResolver {
public:
    struct Entry {
        std::string key;
        std::string value;
        int priority;
    };

    ConfigResolver() : entries_(), resolved_(false) {}

    void addSource(const char* prefix, int priority) {
        // Scan environment for variables with given prefix
        extern char** environ;
        size_t plen = strlen(prefix);
        for (char** env = environ; *env; ++env) {
            if (strncmp(*env, prefix, plen) == 0) {
                std::string pair(*env);
                size_t eq = pair.find('=');
                if (eq != std::string::npos) {
                    Entry e;
                    e.key = pair.substr(plen, eq - plen);
                    e.value = pair.substr(eq + 1);
                    e.priority = priority;
                    entries_.push_back(e);
                }
            }
        }
    }

    std::string resolve(const std::string& key) const {
        int best = -1;
        std::string result;
        for (const auto& e : entries_) {
            if (e.key == key && e.priority > best) {
                best = e.priority;
                result = e.value;
            }
        }
        return result;
    }

private:
    std::vector<Entry> entries_;
    bool resolved_;
};

class AuditLogger {
public:
    enum Facility { LOCAL, SYSLOG_REMOTE };

    AuditLogger(Facility f) : facility_(f) {
        if (facility_ == SYSLOG_REMOTE) {
            openlog("cicd-pipeline", LOG_PID | LOG_NDELAY, LOG_LOCAL0);
        }
    }

    ~AuditLogger() {
        if (facility_ == SYSLOG_REMOTE) {
            closelog();
        }
    }

    // Log a structured audit event
    void logEvent(const char* category, const std::string& detail) {
        char timestamp[64];
        time_t now = time(nullptr);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));

        // Build the message with category prefix
        char msgbuf[1024];
        snprintf(msgbuf, sizeof(msgbuf), "[%s] %s: ", timestamp, category);

        // Append detail - this is the formatted output path
        size_t used = strlen(msgbuf);
        size_t remaining = sizeof(msgbuf) - used - 1;
        if (detail.size() < remaining) {
            memcpy(msgbuf + used, detail.c_str(), detail.size());
            msgbuf[used + detail.size()] = '\0';
        }

        emit(msgbuf);
    }

    // Log with interpolation of config values into a template
    void logTemplate(const char* tmpl, const ConfigResolver& cfg, const std::string& key) {
        std::string val = cfg.resolve(key);
        char intermediate[512];
        snprintf(intermediate, sizeof(intermediate), tmpl, val.c_str());
        emit(intermediate);
    }

private:
    void emit(const char* msg) {
        if (facility_ == SYSLOG_REMOTE) {
            // syslog with the pre-formatted message
            syslog(LOG_INFO, msg);  // <-- format string vulnerability
        } else {
            fprintf(stderr, "%s\n", msg);
        }
    }

    Facility facility_;
};

class StageExecutor {
public:
    StageExecutor(const ConfigResolver& cfg, AuditLogger& logger)
        : cfg_(cfg), logger_(logger) {}

    int runStage(const std::string& stageName) {
        std::string cmd = cfg_.resolve(stageName + "_CMD");
        if (cmd.empty()) {
            logger_.logEvent("SKIP", std::string("No command for stage: ") + stageName);
            return 0;
        }

        // Audit the execution
        logger_.logTemplate("Executing stage with config: %s", cfg_, stageName + "_CMD");

        // Execute (simplified - real impl would use fork/exec)
        logger_.logEvent("EXEC", std::string("Running: ") + cmd);
        int rc = system(cmd.c_str());

        char rcbuf[64];
        snprintf(rcbuf, sizeof(rcbuf), "Stage %s exited with code %d", stageName.c_str(), rc);
        logger_.logEvent("RESULT", std::string(rcbuf));
        return rc;
    }

private:
    const ConfigResolver& cfg_;
    AuditLogger& logger_;
};

} // namespace pipeline

int main(int argc, char* argv[]) {
    using namespace pipeline;

    ConfigResolver cfg;
    // Priority 10: CI system variables (CICD_ prefix)
    cfg.addSource("CICD_", 10);
    // Priority 5: fallback variables (PIPELINE_ prefix)
    cfg.addSource("PIPELINE_", 5);

    // Determine logging facility from config
    std::string logMode = cfg.resolve("LOG_MODE");
    AuditLogger::Facility fac = (logMode == "syslog") 
        ? AuditLogger::SYSLOG_REMOTE 
        : AuditLogger::LOCAL;

    AuditLogger logger(fac);
    StageExecutor executor(cfg, logger);

    // Run pipeline stages
    std::vector<std::string> stages = {"BUILD", "TEST", "DEPLOY"};

    logger.logEvent("PIPELINE", "Starting CI/CD pipeline execution");

    for (const auto& stage : stages) {
        int rc = executor.runStage(stage);
        if (rc != 0) {
            logger.logEvent("ABORT", std::string("Pipeline failed at stage: ") + stage);
            return 1;
        }
    }

    logger.logEvent("PIPELINE", "Pipeline completed successfully");
    return 0;
}
